const card = document.querySelector('.narrator.card');
const out = { status: card?.querySelector('.insp__head .muted')?.textContent, collapsed: card?.querySelector('.narrator__caption')?.textContent?.slice(0,80) };
card.dispatchEvent(new MouseEvent('mouseover', {bubbles: true, relatedTarget: document.body}));
await new Promise(r => setTimeout(r, 300));
out.full = !!card.querySelector('.narrator__caption--full');
out.fullLen = card.querySelector('.narrator__caption')?.textContent?.length;
card.dispatchEvent(new MouseEvent('mouseout', {bubbles: true, relatedTarget: document.body}));
await new Promise(r => setTimeout(r, 300));
out.collapsedAgain = !card.querySelector('.narrator__caption--full');
out

